module casino_profit_calculator (input [15:0] x_in, input [15:0] p_in, output [31:0] profit); reg [31:0] x_q16, p_q16; reg [31:0] x_over_100_q16; reg [31:0] one_minus_x_over_100, one_minus_p_q16; reg [63:0] product_full; reg [31:0] product_q16, ev_q16; reg [31:0] n1, n2, n3, n4, n5, n6, n7, n8, n9, n10; reg [31:0] max_profit; x_q16 = x_in << 8; p_q16 = p_in << 8; x_over_100_q16 = (x_in << 8) / 100; one_minus_x_over_100 = 0x00010000 - x_over_100_q16; one_minus_p_q16 = 0x00010000 - p_q16; product_full = one_minus_p_q16 * one_minus_x_over_100; product_q16 = product_full >> 16; ev_q16 = p_q16 - product_q16; n1 = ev_q16; n2 = n1 + ev_q16; n3 = n2 + ev_q16; n4 = n3 + ev_q16; n5 = n4 + ev_q16; n6 = n5 + ev_q16; n7 = n6 + ev_q16; n8 = n7 + ev_q16; n9 = n8 + ev_q16; n10 = n9 + ev_q16; max_profit = 0; if (n1 > max_profit) max_profit = n1; if (n2 > max_profit) max_profit = n2; if (n3 > max_profit) max_profit = n3; if (n4 > max_profit) max_profit = n4; if (n5 > max_profit) max_profit = n5; if (n6 > max_profit) max_profit = n6; if (n7 > max_profit) max_profit = n7; if (n8 > max_profit) max_profit = n8; if (n9 > max_profit) max_profit = n9; if (n10 > max_profit) max_profit = n10; assign profit = max_profit; endmodule